const items = $input.all();
const content = items[0].json.message.content;

let analysis;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/s);
  analysis = jsonMatch ? JSON.parse(jsonMatch[0]) : { summary: content };
} catch (e) {
  analysis = { summary: content, parseError: true };
}

const transcript = $('Webhook').item.json.body.transcript || '';
const wordCount = transcript.split(/\s+/).length;

// Count speakers
const speakerMatches = transcript.match(/^[A-Z][a-zA-Z\s]+:/gm) || [];
const speakers = [...new Set(speakerMatches.map(s => s.replace(':', '').trim()))];

return [{
  json: {
    wordCount,
    speakerCount: speakers.length,
    speakers,
    themeCount: (analysis.themes || []).length,
    themes: analysis.themes || [],
    sentiment: analysis.sentiment || {},
    keyQuotes: analysis.keyQuotes || [],
    actionItems: analysis.actionItems || [],
    followUpQuestions: analysis.followUpQuestions || [],
    summary: analysis.summary || '',
    analyzedAt: new Date().toISOString()
  }
}];
